//! V4 signed URLs (`GOOG4-RSA-SHA256`) with a service-account key, exactly
//! as google-cloud-storage's `generate_signed_url_v4` builds them (the
//! tests compare against a URL generated by that library).

use std::time::{SystemTime, UNIX_EPOCH};

use fsfast_core::{Error, Result};
use sha2::{Digest as _, Sha256};

use crate::auth::jwt::ServiceAccountKey;
use crate::path::{quote, quote_keep_slash};

/// The longest validity V4 signatures allow (seven days).
pub const MAX_EXPIRATION_SECS: u64 = 604_800;

/// `YYYYMMDDTHHMMSSZ` for `t`.
pub fn v4_timestamp(t: SystemTime) -> String {
    let secs = t
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0) as i64;
    let days = secs.div_euclid(86_400);
    let rem = secs.rem_euclid(86_400);
    let (y, m, d) = civil_from_days(days);
    format!(
        "{y:04}{m:02}{d:02}T{:02}{:02}{:02}Z",
        rem / 3600,
        rem % 3600 / 60,
        rem % 60
    )
}

/// Proleptic Gregorian date of a day count since 1970-01-01 (Howard
/// Hinnant's algorithm).
fn civil_from_days(z: i64) -> (i64, i64, i64) {
    let z = z + 719_468;
    let era = if z >= 0 { z } else { z - 146_096 } / 146_097;
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    (if m <= 2 { y + 1 } else { y }, m, d)
}

/// A V4 signed URL for `method` on `bucket/object` at `endpoint`
/// (`scheme://host[:port]`), valid for `expires_secs` from `now`.
#[allow(clippy::too_many_arguments)]
pub fn signed_url_v4(
    key: &ServiceAccountKey,
    endpoint: &str,
    method: &str,
    bucket: &str,
    object: &str,
    generation: Option<&str>,
    expires_secs: u64,
    now: SystemTime,
) -> Result<String> {
    if expires_secs > MAX_EXPIRATION_SECS {
        return Err(Error::invalid_input(format!(
            "Max allowed expiration interval is seven days {MAX_EXPIRATION_SECS}"
        )));
    }
    let host = fsfast_http_transport::Url::parse(endpoint)
        .ok()
        .and_then(|u| {
            u.host_str().map(|h| match u.port() {
                Some(p) => format!("{h}:{p}"),
                None => h.to_owned(),
            })
        })
        .ok_or_else(|| Error::invalid_input(format!("invalid endpoint {endpoint:?}")))?;
    let timestamp = v4_timestamp(now);
    let datestamp = &timestamp[..8];
    let scope = format!("{datestamp}/auto/storage/goog4_request");
    let credential = format!("{}/{scope}", key.client_email);
    let resource = format!("/{bucket}/{}", quote_keep_slash(object));
    let mut params = vec![
        ("X-Goog-Algorithm", "GOOG4-RSA-SHA256".to_owned()),
        ("X-Goog-Credential", credential),
        ("X-Goog-Date", timestamp.clone()),
        ("X-Goog-Expires", expires_secs.to_string()),
        ("X-Goog-SignedHeaders", "host".to_owned()),
    ];
    if let Some(g) = generation {
        params.push(("generation", g.to_owned()));
    }
    // google-cloud-storage sorts the encoded `name=value` strings.
    let mut encoded: Vec<String> = params
        .iter()
        .map(|(k, v)| format!("{}={}", quote(k), quote(v)))
        .collect();
    encoded.sort();
    let query = encoded.join("&");
    let canonical_request = [
        method,
        &resource,
        &query,
        &format!("host:{host}\n"),
        "host",
        "UNSIGNED-PAYLOAD",
    ]
    .join("\n");
    let hash = hex::encode(Sha256::digest(canonical_request.as_bytes()));
    let string_to_sign = format!("GOOG4-RSA-SHA256\n{timestamp}\n{scope}\n{hash}");
    let sig = hex::encode(key.sign(string_to_sign.as_bytes())?);
    Ok(format!(
        "{endpoint}{resource}?{query}&X-Goog-Signature={sig}"
    ))
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::time::Duration;

    #[test]
    fn timestamps() {
        assert_eq!(v4_timestamp(UNIX_EPOCH), "19700101T000000Z");
        assert_eq!(
            v4_timestamp(UNIX_EPOCH + Duration::from_secs(1_795_547_814)),
            "20261124T191654Z"
        );
        assert_eq!(
            v4_timestamp(UNIX_EPOCH + Duration::from_secs(951_782_400)),
            "20000229T000000Z"
        );
        for d in [-1i64, 0, 59, 365, 11_016, 11_017, 20_000, 2_932_896] {
            let (y, m, dd) = civil_from_days(d);
            assert_eq!(crate::info::days_from_civil(y, m, dd), d, "{d}");
        }
    }
}
